import { useCallback, useEffect, useState } from 'react';

export const FORUM_INTERACTIONS_STORAGE_KEY = 'campus-app-forum-interactions';
export const MAX_FORUM_FAVORITES = 3;

export interface ForumInteractions {
  liked: string[];
  favorited: string[];
}

function uniqueIds(list: unknown): string[] {
  if (!Array.isArray(list)) return [];
  return [...new Set(list.map(item => String(item || '').trim()).filter(Boolean))];
}

export function readForumInteractions(): ForumInteractions {
  try {
    const parsed = JSON.parse(window.localStorage.getItem(FORUM_INTERACTIONS_STORAGE_KEY) || '{}') as Partial<ForumInteractions>;
    return {
      liked: uniqueIds(parsed.liked),
      favorited: uniqueIds(parsed.favorited).slice(0, MAX_FORUM_FAVORITES),
    };
  } catch {
    return { liked: [], favorited: [] };
  }
}

function writeInteractions(next: ForumInteractions) {
  try {
    window.localStorage.setItem(FORUM_INTERACTIONS_STORAGE_KEY, JSON.stringify(next));
    window.dispatchEvent(new CustomEvent('campus-forum-interactions-changed', { detail: next }));
  } catch {
    // ignore quota / private mode
  }
}

function toggleId(list: string[], id: string): string[] {
  return list.includes(id) ? list.filter(item => item !== id) : [...list, id];
}

export function useForumInteractions() {
  const [state, setState] = useState<ForumInteractions>(readForumInteractions);

  useEffect(() => {
    const sync = () => setState(readForumInteractions());
    const onStorage = (event: StorageEvent) => {
      if (event.key === FORUM_INTERACTIONS_STORAGE_KEY) sync();
    };
    window.addEventListener('storage', onStorage);
    window.addEventListener('campus-forum-interactions-changed', sync);
    return () => {
      window.removeEventListener('storage', onStorage);
      window.removeEventListener('campus-forum-interactions-changed', sync);
    };
  }, []);

  const persist = useCallback((next: ForumInteractions) => {
    setState(next);
    writeInteractions(next);
  }, []);

  const isLiked = useCallback((id: string) => state.liked.includes(id), [state.liked]);
  const isFavorited = useCallback((id: string) => state.favorited.includes(id), [state.favorited]);

  const toggleLike = useCallback((id: string) => {
    persist({ ...state, liked: toggleId(state.liked, id) });
    return true;
  }, [persist, state]);

  const toggleFavorite = useCallback((id: string) => {
    if (state.favorited.includes(id)) {
      persist({ ...state, favorited: state.favorited.filter(item => item !== id) });
      return true;
    }
    if (state.favorited.length >= MAX_FORUM_FAVORITES) {
      return false;
    }
    persist({ ...state, favorited: [...state.favorited, id] });
    return true;
  }, [persist, state]);

  return {
    likedIds: state.liked,
    favoritedIds: state.favorited,
    favoriteCount: state.favorited.length,
    favoriteLimit: MAX_FORUM_FAVORITES,
    isLiked,
    isFavorited,
    toggleLike,
    toggleFavorite,
  };
}
