import { upsertWorldbookArchives } from '../../../游戏开局/playerArchive';
import { ForumPost } from '../types';
import { MAX_FORUM_FAVORITES } from '../hooks/useForumInteractions';
import { serializeForumPostsXml } from './forumParser';

export const FORUM_UPDATE_ENTRY_NAME = '校园论坛更新需求';

let lastWrittenSignature = '';
let writeQueue: Promise<void> = Promise.resolve();

function buildForumUpdateEntryContent(posts: ForumPost[]): string {
  if (!posts.length) {
    return [
      '校园论坛更新需求：',
      `  收藏上限: ${MAX_FORUM_FAVORITES}`,
      '  当前没有玩家收藏帖。',
      '  规则:',
      '    - 每轮必须根据本轮剧情创作 1~3 个全新帖子，使用新的帖子 id',
      '    - 禁止复用旧帖 id',
      '    - 禁止给未收藏帖追加回复、改热度、改收藏或重写正文',
      '    - 没有新讨论时输出空容器：<论坛></论坛>',
    ].join('\n');
  }

  return [
    '校园论坛更新需求：',
    `  收藏上限: ${MAX_FORUM_FAVORITES}`,
    '  规则:',
    '    - 每轮必须根据本轮剧情创作 1~3 个全新帖子，使用新的帖子 id',
    '    - 下面列出的帖子是玩家当前收藏帖，必须继续更新：复用原帖 id，使用 delta="true" 只追加新回复楼层',
    '    - 未出现在本条目中的旧帖一律视为未收藏，禁止再更新',
    '    - 不要重写收藏帖的标题和正文，不要删除旧回复',
    '    - 每条收藏帖本轮追加 1~2 条新回复即可',
    '    - 没有新讨论时仍要给每条收藏帖追加新回复，或输出空容器',
    '  收藏帖:',
    serializeForumPostsXml(posts)
      .split('\n')
      .map(line => `    ${line}`)
      .join('\n'),
  ].join('\n');
}

function signatureOf(posts: ForumPost[]): string {
  return JSON.stringify(
    posts.map(post => ({
      id: post.id,
      title: post.title,
      content: post.content,
      likes: post.likes,
      favorites: post.favorites,
      replies: post.replies,
    })),
  );
}

export async function syncFavoritedPostsToWorldbook(posts: ForumPost[]): Promise<void> {
  const limited = posts.slice(0, MAX_FORUM_FAVORITES);
  const signature = signatureOf(limited);
  if (signature === lastWrittenSignature) return;

  const content = buildForumUpdateEntryContent(limited);
  const run = writeQueue.then(async () => {
    if (signature === lastWrittenSignature) return;
    const written = await upsertWorldbookArchives([
      {
        name: FORUM_UPDATE_ENTRY_NAME,
        content,
        enabled: true,
        strategy: {
          type: 'constant',
          keys: [],
          keys_secondary: { logic: 'and_any', keys: [] },
          scan_depth: 'same_as_global',
        },
      },
    ]);
    if (written > 0) {
      lastWrittenSignature = signature;
    }
  });
  writeQueue = run.then(
    () => undefined,
    () => undefined,
  );
  await run;
}
