export const APP_VERSION =
  typeof CAMPUS_APP_VERSION === 'string' && CAMPUS_APP_VERSION ? CAMPUS_APP_VERSION : 'v0.2.0';
export const APP_BUILD_ID =
  typeof CAMPUS_APP_BUILD_ID === 'string' && CAMPUS_APP_BUILD_ID ? CAMPUS_APP_BUILD_ID : 'dev-local';

export type ReleaseChannel = 'dev' | 'release' | 'unknown';
export type SourceKind = 'localhost' | 'githack' | 'jsdelivr' | 'github-raw' | 'unknown';

export interface VersionManifest {
  version: string;
  buildId: string;
  builtAt?: string;
}

export interface RuntimeInfo {
  channel: ReleaseChannel;
  sourceUrl: string;
  sourceKind: SourceKind;
  version: string;
  buildId: string;
}

export interface UpdateCheckResult extends RuntimeInfo {
  latest?: VersionManifest;
  hasUpdate: boolean;
  checkedAt: number;
  error?: string;
}

const DISMISS_KEY = 'campus-app-update-dismissed';
const SCRIPT_NAME = '校园APP浮窗/index.js';
let explicitSourceUrl = '';

export function setRuntimeSourceUrl(url: string) {
  explicitSourceUrl = cleanUrl(url);
}

export function getRuntimeInfo(): RuntimeInfo {
  const sourceUrl = detectSourceUrl();
  let sourceKind = detectSourceKind(sourceUrl);
  if (sourceKind === 'unknown' && isDevBuild()) {
    sourceKind = 'localhost';
  }
  return {
    channel: channelFromKind(sourceKind),
    sourceUrl,
    sourceKind,
    version: APP_VERSION,
    buildId: APP_BUILD_ID,
  };
}

export function isDismissed(buildId: string): boolean {
  if (!buildId) return false;
  try {
    return window.localStorage.getItem(DISMISS_KEY) === buildId;
  } catch {
    return false;
  }
}

export function dismissUpdate(buildId: string) {
  if (!buildId) return;
  try {
    window.localStorage.setItem(DISMISS_KEY, buildId);
  } catch {
    // ignore
  }
}

export async function checkCampusAppUpdate(): Promise<UpdateCheckResult> {
  const runtime = getRuntimeInfo();
  const checkedAt = Date.now();
  if (runtime.channel !== 'release') {
    return { ...runtime, hasUpdate: false, checkedAt };
  }

  const urls = buildManifestUrls(runtime.sourceUrl);
  if (!urls.length) {
    return { ...runtime, hasUpdate: false, checkedAt, error: '无法从当前加载地址推导版本文件' };
  }

  let lastError = '';
  for (const url of urls) {
    try {
      const latest = await fetchManifest(url);
      if (!latest) continue;
      return {
        ...runtime,
        latest,
        hasUpdate: isNewer(runtime, latest),
        checkedAt,
      };
    } catch (error) {
      lastError = error instanceof Error ? error.message : String(error);
    }
  }

  return { ...runtime, hasUpdate: false, checkedAt, error: lastError || '读取远端版本失败' };
}

export async function applyCampusAppUpdate(): Promise<void> {
  const runtime = getRuntimeInfo();
  const urls = buildPurgeUrls(runtime.sourceUrl);
  await Promise.allSettled(
    urls.map(url =>
      fetch(url, { cache: 'no-store', mode: 'no-cors' }).catch(() => undefined),
    ),
  );
  reloadCampusScript();
}

export function reloadCampusScript() {
  const frame = window.frameElement as HTMLIFrameElement | null;
  if (frame) {
    const src = frame.getAttribute('src') || frame.src;
    if (src && src !== 'about:blank') {
      try {
        const next = new URL(src, getParentHref());
        next.searchParams.set('_campus_reload', String(Date.now()));
        frame.src = next.toString();
        return;
      } catch {
        // fall through
      }
    }
  }
  window.location.reload();
}

function getParentHref(): string {
  try {
    return window.parent?.location?.href || window.location.href;
  } catch {
    return window.location.href;
  }
}

function buildPurgeUrls(sourceUrl: string): string[] {
  const urls: string[] = [];
  const push = (url: string) => {
    if (url && !urls.includes(url)) urls.push(url);
  };
  const parsed = parseGithubTarget(sourceUrl);
  if (parsed) {
    const folder = encodePath(parsed.path);
    for (const file of ['index.js', 'version.json']) {
      push(`https://purge.jsdelivr.net/gh/${parsed.user}/${parsed.repo}@${parsed.ref}/${folder}/${file}`);
    }
  }
  const localJs = sourceUrl.replace(/[?#].*$/, '');
  if (/index\.js$/i.test(localJs)) push(localJs);
  return urls;
}

function isNewer(current: VersionManifest, latest: VersionManifest): boolean {
  if (latest.buildId && current.buildId && latest.buildId !== current.buildId) return true;
  const left = normalizeVersion(latest.version);
  const right = normalizeVersion(current.version);
  if (left && right && left !== right) return true;
  return false;
}

function normalizeVersion(version: string): string {
  return String(version || '')
    .trim()
    .replace(/^v/i, '');
}

function isDevBuild(): boolean {
  return typeof CAMPUS_APP_IS_DEV === 'boolean' ? CAMPUS_APP_IS_DEV : false;
}

function channelFromKind(kind: SourceKind): ReleaseChannel {
  if (kind === 'localhost') return 'dev';
  if (kind === 'githack' || kind === 'jsdelivr' || kind === 'github-raw') return 'release';
  return 'unknown';
}

function detectSourceKind(url: string): SourceKind {
  const value = decodeURIComponentSafe(url).toLowerCase();
  if (!value) return 'unknown';
  if (value.startsWith('blob:') || value.startsWith('about:') || value.startsWith('webpack:') || value.startsWith('file:')) return 'unknown';
  if (/localhost|127\.0\.0\.1|0\.0\.0\.0/.test(value) && /:\d+/.test(value)) return 'localhost';
  if (value.includes('githack.com')) return 'githack';
  if (value.includes('jsdelivr.net')) return 'jsdelivr';
  if (value.includes('raw.githubusercontent.com') || value.includes('github.com')) return 'github-raw';
  return 'unknown';
}

function detectSourceUrl(): string {
  const candidates = collectCandidateUrls();
  const ranked = candidates
    .map(url => ({ url, score: scoreSourceUrl(url) }))
    .filter(item => item.score > 0)
    .sort((a, b) => b.score - a.score);
  return ranked[0]?.url || '';
}

function collectCandidateUrls(): string[] {
  const found = new Set<string>();
  const add = (value: string) => {
    extractImportUrls(value).forEach(url => found.add(url));
    const cleaned = cleanUrl(value);
    if (cleaned) found.add(cleaned);
  };

  add(explicitSourceUrl);
  add(moduleUrl());
  add(currentScriptSrc());
  scriptTagSrcs().forEach(add);
  resourceUrls().forEach(add);
  add(stackUrl());
  add(frameSrc());
  add(documentUrl());
  collectDocumentText(document).forEach(add);
  try {
    if (window.parent && window.parent !== window) {
      collectDocumentText(window.parent.document).forEach(add);
    }
  } catch {
    // ignore cross-origin parent
  }
  return [...found];
}

function collectDocumentText(doc: Document): string[] {
  const texts: string[] = [];
  try {
    texts.push(doc.documentElement?.outerHTML || '');
  } catch {
    // ignore
  }
  try {
    Array.from(doc.querySelectorAll('textarea, pre, code, [contenteditable="true"]')).forEach(node => {
      texts.push((node as HTMLElement).innerText || '');
      texts.push((node as HTMLTextAreaElement).value || '');
    });
  } catch {
    // ignore
  }
  return texts.filter(Boolean);
}

function extractImportUrls(text: string): string[] {
  if (!text) return [];
  const urls = new Set<string>();
  const patterns = [
    /import\s*\(\s*['"](https?:\/\/[^'"]+)['"]/gi,
    /import\s*['"](https?:\/\/[^'"]+)['"]/gi,
    /https?:\/\/[^\s"'<>\\]+(?:校园APP浮窗|%E6%A0%A1%E5%9B%ADAPP%E6%B5%AE%E7%AA%97)[^\s"'<>\\]*/gi,
    /https?:\/\/(?:localhost|127\.0\.0\.1|0\.0\.0\.0):\d+\/[^\s"'<>\\]*index\.js[^\s"'<>\\]*/gi,
  ];
  for (const pattern of patterns) {
    for (const match of text.matchAll(pattern)) {
      const url = cleanUrl(match[1] || match[0] || '');
      if (url.startsWith('http')) urls.add(url);
    }
  }
  return [...urls];
}

function scoreSourceUrl(url: string): number {
  const kind = detectSourceKind(url);
  const decoded = decodeURIComponentSafe(url);
  const isCampusScript = /校园APP浮窗|%E6%A0%A1%E5%9B%ADAPP%E6%B5%AE%E7%AA%97/i.test(decoded);
  const isIndexJs = /index\.js/i.test(decoded);
  if (!isCampusScript && !isIndexJs && kind === 'localhost') return 0;
  let score = 0;
  if (kind === 'localhost' && isCampusScript) score += 160;
  else if (kind === 'localhost' && isIndexJs) score += 130;
  if (kind === 'githack' || kind === 'jsdelivr') score += 110;
  if (kind === 'github-raw') score += 100;
  if (isCampusScript) score += 60;
  if (isIndexJs) score += 20;
  if (kind === 'unknown') score -= 80;
  if (/^(blob:|about:|webpack:|file:|chrome-extension:)/i.test(url)) score -= 200;
  return score;
}

function decodeURIComponentSafe(value: string): string {
  try {
    return decodeURIComponent(value);
  } catch {
    return value;
  }
}

function moduleUrl(): string {
  try {
    return String(import.meta.url || '');
  } catch {
    return '';
  }
}

function resourceUrls(): string[] {
  const names: string[] = [];
  const collect = (perf: Performance | undefined) => {
    try {
      perf?.getEntriesByType('resource').forEach(entry => names.push(entry.name));
      perf?.getEntriesByType('navigation').forEach(entry => names.push(entry.name));
    } catch {
      // ignore
    }
  };
  collect(window.performance);
  try {
    if (window.parent && window.parent !== window) collect(window.parent.performance);
  } catch {
    // ignore
  }
  return names;
}

function currentScriptSrc(): string {
  try {
    return (document.currentScript as HTMLScriptElement | null)?.src || '';
  } catch {
    return '';
  }
}

function scriptTagSrcs(): string[] {
  try {
    return Array.from(document.scripts)
      .map(item => item.src)
      .filter(Boolean)
      .reverse();
  } catch {
    return [];
  }
}

function stackUrl(): string {
  try {
    throw new Error('campus-app-source');
  } catch (error) {
    const stack = String((error as Error).stack || '');
    const matches = stack.match(/https?:\/\/[^\s)'"]+/g) || [];
    return matches.find(url => /校园APP浮窗|%E6%A0%A1%E5%9B%ADAPP%E6%B5%AE%E7%AA%97|index\.js/i.test(url)) || matches[0] || '';
  }
}

function frameSrc(): string {
  try {
    const frame = window.frameElement as HTMLIFrameElement | null;
    return frame?.src || '';
  } catch {
    return '';
  }
}

function documentUrl(): string {
  try {
    return document.location?.href || '';
  } catch {
    return '';
  }
}

function cleanUrl(url: string): string {
  if (!url) return '';
  const cleaned = url
    .replace(/[)\]'"]+$/g, '')
    .replace(/#.*$/, '')
    .trim();
  if (/^(file:|webpack:|blob:|about:|chrome-extension:)/i.test(cleaned)) return '';
  return cleaned;
}

function buildManifestUrls(sourceUrl: string): string[] {
  const urls: string[] = [];
  const push = (url: string) => {
    if (url && !urls.includes(url)) urls.push(url);
  };
  push(toGitHubRawManifest(sourceUrl));
  if (detectSourceKind(sourceUrl) === 'githack') push(toManifestUrl(sourceUrl));
  push(toJsdelivrManifest(sourceUrl));
  push(toManifestUrl(sourceUrl));
  return urls.map(bust);
}

function toManifestUrl(sourceUrl: string): string {
  if (!sourceUrl) return '';
  try {
    const url = new URL(sourceUrl, document.baseURI);
    if (!/^https?:$/i.test(url.protocol)) return '';
    url.search = '';
    url.hash = '';
    if (/index\.js$/i.test(url.pathname)) {
      url.pathname = url.pathname.replace(/index\.js$/i, 'version.json');
      return url.toString();
    }
    if (url.pathname.endsWith('/')) {
      url.pathname = `${url.pathname}version.json`;
      return url.toString();
    }
    const folder = url.pathname.replace(/\/[^/]+$/, '/');
    url.pathname = `${folder}version.json`;
    return url.toString();
  } catch {
    return '';
  }
}

function toGitHubRawManifest(sourceUrl: string): string {
  const parsed = parseGithubTarget(sourceUrl);
  if (!parsed) return '';
  return `https://raw.githubusercontent.com/${parsed.user}/${parsed.repo}/${parsed.ref}/${encodePath(parsed.path)}/version.json`;
}

function toJsdelivrManifest(sourceUrl: string): string {
  const parsed = parseGithubTarget(sourceUrl);
  if (!parsed) return '';
  return `https://testingcf.jsdelivr.net/gh/${parsed.user}/${parsed.repo}@${parsed.ref}/${encodePath(parsed.path)}/version.json`;
}

function parseGithubTarget(sourceUrl: string): { user: string; repo: string; ref: string; path: string } | null {
  try {
    const url = new URL(sourceUrl, document.baseURI);
    const host = url.hostname.toLowerCase();
    const parts = decodeURI(url.pathname).replace(/^\/+|\/+$/g, '').split('/');
    if (host.includes('githack.com') && parts.length >= 4) {
      const [user, repo, ref, ...rest] = parts;
      return { user, repo, ref, path: folderPath(rest) };
    }
    if (host.includes('jsdelivr.net') && parts[0] === 'gh' && parts.length >= 3) {
      const [user, repoRef, ...rest] = parts.slice(1);
      const at = repoRef.lastIndexOf('@');
      const repo = at >= 0 ? repoRef.slice(0, at) : repoRef;
      const ref = at >= 0 ? repoRef.slice(at + 1) : 'main';
      return { user, repo, ref, path: folderPath(rest) };
    }
    if (host === 'raw.githubusercontent.com' && parts.length >= 4) {
      const [user, repo, ref, ...rest] = parts;
      return { user, repo, ref, path: folderPath(rest) };
    }
  } catch {
    return null;
  }
  return null;
}

function encodePath(value: string): string {
  return value
    .split('/')
    .filter(Boolean)
    .map(encodeURIComponent)
    .join('/');
}

function folderPath(rest: string[]): string {
  const joined = rest.join('/');
  if (!joined) return SCRIPT_NAME.replace(/\/index\.js$/, '');
  return joined.replace(/\/index\.js$/i, '').replace(/\/version\.json$/i, '') || SCRIPT_NAME.replace(/\/index\.js$/, '');
}

function bust(url: string): string {
  const joiner = url.includes('?') ? '&' : '?';
  return `${url}${joiner}t=${Date.now()}`;
}

async function fetchManifest(url: string): Promise<VersionManifest | null> {
  if (!/^https?:/i.test(url)) return null;
  const response = await fetch(url, { cache: 'no-store' });
  if (!response.ok) throw new Error(`HTTP ${response.status}`);
  const data = (await response.json()) as Partial<VersionManifest>;
  if (!data || typeof data !== 'object') return null;
  const version = String(data.version || '').trim();
  const buildId = String(data.buildId || '').trim();
  if (!version && !buildId) return null;
  return {
    version: version || APP_VERSION,
    buildId,
    builtAt: String(data.builtAt || ''),
  };
}

export function channelLabel(channel: ReleaseChannel): string {
  if (channel === 'dev') return '研发版';
  if (channel === 'release') return '正式版';
  return '未识别';
}

export function sourceKindLabel(kind: SourceKind): string {
  switch (kind) {
    case 'localhost':
      return '本地服务';
    case 'githack':
      return 'GitHack';
    case 'jsdelivr':
      return 'jsDelivr';
    case 'github-raw':
      return 'GitHub Raw';
    default:
      return '未知来源';
  }
}
