import { useEffect } from 'react';
import { showToast } from '../ui/Toast';
import { useCampusUpdate } from '../../hooks/useCampusUpdate';

let runtimeTipShown = false;

export function UpdateBanner() {
  const { result } = useCampusUpdate();

  useEffect(() => {
    if (!result || runtimeTipShown) return;
    runtimeTipShown = true;
    showToast(result.version, 'info', 2500);
  }, [result]);

  return null;
}
