function createPlayer(data?: MvuPlayer): Player {
  const name = String(data?.姓名 || '').trim();
  const identity = String(data?.身份 || '').trim();
  return {
    name: name || '玩家',
    identity: identity || '学生',
    avatar: null,
    clothing: {
      upper: data?.当前穿搭?.上装 || '',
      lower: data?.当前穿搭?.下装 || '',
      accessories: data?.当前穿搭?.配饰 || '',
      shoes: data?.当前穿搭?.鞋子 || '',
    },
  };
}

function asPartText(value: unknown): string {
  if (!value) return '';
  if (typeof value === 'string') return value;
  if (typeof value === 'object') {
    const record = value as Record<string, unknown>;
    return typeof record.描述 === 'string' ? record.描述 : '';
  }
  return String(value);
}

function stripLeadingTag(text: string, tag?: string): string {
  const value = String(text || '').trim();
  const label = String(tag || '').trim();
  if (!value) return '';
  if (!label) return value;
  const escaped = label.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return value
    .replace(new RegExp(`^${escaped}(?:\\s*[·,，、:/|-]+\\s*|\\s+)`), '')
    .replace(new RegExp(`(?:^|[\\s·,，、:/|-]+)${escaped}(?=$|[\\s·,，、:/|-]+)`), ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function asFriendFlag(value: unknown): boolean {
  if (typeof value === 'boolean') return value;
  if (typeof value === 'number') return value !== 0;
  if (typeof value === 'string') {
    const text = value.trim().toLowerCase();
    return ['true', '1', 'yes', 'on', '是', '好友'].includes(text);
  }
  if (Array.isArray(value) && value.length) return asFriendFlag(value[0]);
  if (value && typeof value === 'object' && 'value' in (value as Record<string, unknown>)) {
    return asFriendFlag((value as Record<string, unknown>).value);
  }
  return false;
}

function createCharacter(id: string, data: MvuCharacter): Character {
  const figure = (data.身体数据 || {}) as any;
  const experience = (data as any).经验档案 || (data as any).隐私档案 || {};
  const fetishTags = Array.isArray(experience.性癖标签)
    ? experience.性癖标签.map(String)
    : typeof experience.性癖 === 'string' && experience.性癖
      ? [experience.性癖]
      : [];

  return {
    id,
    name: data.姓名 || id,
    nickname: String(data.网名 || '').trim(),
    isFriend: asFriendFlag(data.好友位),
    identity: data.身份,
    className: data.班级,
    location: data.当前所在地,
    affinity: Number(data.好感度) || 0,
    avatar: null,
    personality: data.性格,
    innerThoughts: data.当前心声,
    appearance: {
      features: data.容貌特征?.特征 || '',
      hairstyle: data.容貌特征?.发型 || '',
      skin: data.容貌特征?.肤色 || '',
      temperament: data.容貌特征?.气质 || '',
    },
    figure: {
      chestCup: typeof figure.胸部 === 'object' ? String(figure.胸部?.罩杯 || '').trim() : '',
      chest: stripLeadingTag(asPartText(figure.胸部), typeof figure.胸部 === 'object' ? figure.胸部?.罩杯 : ''),
      waistType: typeof figure.腰部 === 'object' ? String(figure.腰部?.腰型 || '').trim() : '',
      waist: stripLeadingTag(asPartText(figure.腰部), typeof figure.腰部 === 'object' ? figure.腰部?.腰型 : ''),
      hipType: typeof figure.臀部 === 'object' ? String(figure.臀部?.臀型 || '').trim() : '',
      buttocks: stripLeadingTag(asPartText(figure.臀部), typeof figure.臀部 === 'object' ? figure.臀部?.臀型 : ''),
      legType: typeof figure.腿部 === 'object' ? String(figure.腿部?.腿型 || '').trim() : '',
      legs: stripLeadingTag(asPartText(figure.腿部), typeof figure.腿部 === 'object' ? figure.腿部?.腿型 : ''),
    },
    privateParts: {
      pussy: data.隐私部位?.小穴 || '',
      anus: data.隐私部位?.菊穴 || '',
    },
    privateProfile: {
      isVirgin: typeof experience.是否处女 === 'boolean' ? experience.是否处女 : true,
      fetishTags,
      sexCount: Number(experience.经验次数 || 0),
    },
  };
}

function createRule(id: string, data: MvuRule): SchoolRule {
  return {
    id,
    title: data.标题 || id,
    content: data.内容 || '',
    category: data.分类 || '其他',
    enabled: data.是否启用 !== false,
    locationNames: Array.isArray(data.生效地点) ? data.生效地点 : [],
  };
}

function parseRulesFromMvu(raw: unknown): SchoolRule[] {
  return Object.entries(parseMvuRules(raw)).map(([id, rule]) => createRule(id, rule));
}

function readEventTimeField(time: any, keys: string[], fallback: number): number {
  if (!time || typeof time !== 'object') return fallback;
  for (const key of keys) {
    const n = readMvuNumber(time[key]);
    if (n != null) return n;
  }
  return fallback;
}

function eventTimestamp(time: any, year: number): number {
  const y = readEventTimeField(time, ['年', 'year'], year);
  const month = Math.min(12, Math.max(1, readEventTimeField(time, ['月', 'month'], 1)));
  const day = Math.min(31, Math.max(1, readEventTimeField(time, ['日', 'day'], 1)));
  const hour = Math.min(23, Math.max(0, readEventTimeField(time, ['小时', 'hour'], 0)));
  const minute = Math.min(59, Math.max(0, readEventTimeField(time, ['分钟', 'minute'], 0)));
  return new Date(y, month - 1, day, hour, minute, 0, 0).getTime();
}

function asBuildingEvents(value: unknown): MvuBuildingEvent[] {
  if (Array.isArray(value)) {
    return value.filter((item): item is MvuBuildingEvent => Boolean(item) && typeof item === 'object' && !Array.isArray(item));
  }
  if (value && typeof value === 'object') {
    return Object.entries(value as Record<string, unknown>)
      .filter(([key]) => key !== '$meta')
      .map(([, item]) => item)
      .filter((item): item is MvuBuildingEvent => Boolean(item) && typeof item === 'object' && !Array.isArray(item));
  }
  return [];
}

function createEvent(data: MvuBuildingEvent, year: number, id: string): BuildingEvent {
  const startTime = eventTimestamp(data.开始时间, year);
  let endTime = eventTimestamp(data.结束时间, year);
  if (Number.isFinite(startTime) && Number.isFinite(endTime) && endTime < startTime) {
    const rolled = new Date(endTime);
    rolled.setFullYear(rolled.getFullYear() + 1);
    endTime = rolled.getTime();
  }
  return {
    id,
    name: String(data.活动名称 || '').trim() || '未命名活动',
    description: String(data.活动描述 || '').trim(),
    startTime,
    endTime,
    stages: (Array.isArray(data.活动环节) ? data.活动环节 : []).map((stage, index) => ({
      id: `${id}-s${index + 1}`,
      name: stage.环节名称 || `环节${index + 1}`,
      description: stage.环节描述 || '',
      startTime: eventTimestamp(stage.开始时间, year),
      endTime: eventTimestamp(stage.结束时间, year),
    })),
  };
}

function getBuildingColor(type: MvuBuilding['建筑类型']): string {
  const colors: Record<MvuBuilding['建筑类型'], string> = {
    餐饮娱乐: 'bg-[#FFEDD4] border-[#FAC280]',
    学习设施: 'bg-[#DBEAFE] border-[#91C6FF]',
    运动设施: 'bg-[#FFE2E2] border-[#FDA6A5]',
    宿舍生活: 'bg-[#F3E8FF] border-[#DAB5FD]',
    自然环境: 'bg-[#DBFCE7] border-[#7BF1A8]',
  };
  return colors[type] || colors.自然环境;
}

function createBuilding(name: string, data: MvuBuilding, year: number): CampusBuilding {
  return {
    id: name,
    name,
    x: Number(data.X坐标) || 0,
    y: Number(data.Y坐标) || 0,
    width: Number(data.宽度) || 5,
    height: Number(data.高度) || 3,
    color: getBuildingColor(data.建筑类型),
    description: data.建筑描述,
    facilityType: data.建筑类型,
    events: asBuildingEvents(data.建筑活动).map((event, index) => createEvent(event, year, `${name}-${index}`)),
  };
}

function omitMvuMeta<T extends Record<string, any>>(record: T | null | undefined): T {
  if (!record || typeof record !== 'object' || Array.isArray(record)) {
    return {} as T;
  }
  return Object.fromEntries(
    Object.entries(record).filter(([key, value]) => key !== '$meta' && value && typeof value === 'object' && !Array.isArray(value)),
  ) as T;
}

function createChatGroup(id: string, data: { 群名: string; 简介: string; 成员: string[] }): ChatGroup {
  return {
    id,
    name: data.群名 || id,
    summary: data.简介 || '',
    memberNames: Array.isArray(data.成员) ? data.成员.map(String).filter(Boolean) : [],
  };
}

function groupIncludesPlayer(group: ChatGroup, playerName: string): boolean {
  const aliases = [playerName, '{{user}}', 'user'].map(item => String(item || '').trim()).filter(Boolean);
  return group.memberNames.some(member => aliases.includes(String(member || '').trim()));
}

function parseGroupsFromMvu(raw: unknown, playerName = ''): ChatGroup[] {
  return Object.entries(parseMvuChatGroups(raw))
    .map(([id, group]) => createChatGroup(id, group))
    .filter(group => !playerName || groupIncludesPlayer(group, playerName));
}

function formatStatusTime(time?: MvuTime): string {
  if (!time || time.小时 == null || time.分钟 == null || Number.isNaN(Number(time.小时)) || Number.isNaN(Number(time.分钟))) {
    return '--:--';
  }
  return `${String(time.小时).padStart(2, '0')}:${String(time.分钟).padStart(2, '0')}`;
}

function buildMvuState(data: Partial<ReturnType<typeof getFullMvuData>> = getFullMvuData()) {
  const year = readMvuNumber(data.时间?.年);
  const storyYear = year ?? new Date().getFullYear();
  const characters = omitMvuMeta(data.角色);
  const buildings = omitMvuMeta(data.校园建筑);
  return {
    player: createPlayer(data.玩家),
    characters: Object.entries(characters).map(([id, character]) => createCharacter(id, character as MvuCharacter)),
    rules: parseRulesFromMvu(data.校规),
    groups: parseGroupsFromMvu(data.聊天群组, String(data.玩家?.姓名 || '').trim()),
    buildings: Object.entries(buildings).map(([name, building]) => createBuilding(name, building as MvuBuilding, storyYear)),
    time: data.时间,
  };
}

async function setMvuRules(nextRules: SchoolRule[]): Promise<void> {
  const data = getFullMvuData();
  const existingMeta = (data.校规 as any)?.$meta || { extensible: true };
  const persisted = nextRules.filter(rule => rule.pendingAction !== 'add');
  const next: Record<string, any> = {
    $meta: existingMeta,
  };

  for (const rule of persisted) {
    const category = String(rule.category || '其他').trim() || '其他';
    const title = String(rule.title || '').trim() || '未命名校规';
    if (!isPlainObjectLike(next[category])) {
      const prevCategoryMeta = (data.校规 as any)?.[category]?.$meta;
      next[category] = { $meta: prevCategoryMeta || { extensible: true } };
    }
    next[category][title] = {
      内容: rule.content,
      是否启用: rule.enabled !== false,
      生效地点: Array.isArray(rule.locationNames) ? rule.locationNames : [],
    };
  }

  await setMvuVariable('校规', next);
}

function isPlainObjectLike(value: unknown): value is Record<string, any> {
  return !!value && typeof value === 'object' && !Array.isArray(value);
}

async function setMvuBuildings(buildings: CampusBuilding[]): Promise<void> {
  const data = getFullMvuData();
  const existingMeta = (data.校园建筑 as any)?.$meta || { extensible: true };
  const nextBuildings = {
    $meta: existingMeta,
    ...Object.fromEntries(
    buildings.map(building => [building.name, {
      X坐标: building.x,
      Y坐标: building.y,
      宽度: building.width,
      高度: building.height,
      建筑类型: building.facilityType || data.校园建筑?.[building.name]?.建筑类型 || '学习设施',
      建筑描述: building.description || '',
      建筑活动: (building.events || []).map(event => ({
        活动名称: event.name,
        开始时间: {
          月: new Date(event.startTime).getMonth() + 1,
          日: new Date(event.startTime).getDate(),
          小时: new Date(event.startTime).getHours(),
          分钟: new Date(event.startTime).getMinutes(),
        },
        结束时间: {
          月: new Date(event.endTime).getMonth() + 1,
          日: new Date(event.endTime).getDate(),
          小时: new Date(event.endTime).getHours(),
          分钟: new Date(event.endTime).getMinutes(),
        },
        活动描述: event.description,
        活动环节: (event.stages || []).map(stage => ({
          环节名称: stage.name,
          开始时间: {
            月: new Date(stage.startTime).getMonth() + 1,
            日: new Date(stage.startTime).getDate(),
            小时: new Date(stage.startTime).getHours(),
            分钟: new Date(stage.startTime).getMinutes(),
          },
          结束时间: {
            月: new Date(stage.endTime).getMonth() + 1,
            日: new Date(stage.endTime).getDate(),
            小时: new Date(stage.endTime).getHours(),
            分钟: new Date(stage.endTime).getMinutes(),
          },
          环节描述: stage.description,
        })),
      })),
    }])
  ),
  };
  await setMvuVariable('校园建筑', nextBuildings);
}


type Tab = 'profile' | 'contacts' | 'rules' | 'map' | 'forum' | 'settings' | 'appSettings' | null;

export function PhoneSimulator({
  initialTab = null,
  hideHomeNav = false,
  initialWorkshopModule = 'world',
  onCloseToMenu,
}: {
  initialTab?: Tab;
  hideHomeNav?: boolean;
  initialWorkshopModule?: 'world' | 'enrollment';
  onCloseToMenu?: () => void;
} = {}) {
  const mvuData = useMvuSnapshot();
  const [activeTab, setActiveTab] = useState<Tab>(initialTab);
  const [player, setPlayer] = useState<Player>(() => {
    const created = createPlayer(mvuData.玩家);
    return { ...created, avatar: loadAvatarStore().player || created.avatar };
  });
  const [characters, setCharacters] = useState<Character[]>([]);
  const [groups, setGroups] = useState<ChatGroup[]>([]);
  const [rules, setRules] = useState<SchoolRule[]>([]);
  const [buildings, setBuildings] = useState<CampusBuilding[]>([]);
  const [selectedChar, setSelectedChar] = useState<Character | null>(null);
  const [statusTime, setStatusTime] = useState('--:--');
  const buildingsWritePending = useRef(false);
  const { hasUpdate } = useCampusUpdate();
  const { isDark } = useCampusTheme();
  useForumFavoriteWorldbookSync();

  useEffect(() => {
    const next = buildMvuState(mvuData);
    const hasAny =
      Boolean(next.player?.name && next.player.name !== '玩家') ||
      next.characters.length > 0 ||
      next.groups.length > 0 ||
      next.rules.length > 0 ||
      next.buildings.length > 0;
    if (!hasAny) {
      return;
    }
    const storedAvatars = loadAvatarStore();
    setPlayer(prev => ({ ...next.player, avatar: storedAvatars.player || prev.avatar }));
    setCharacters(prev => {
      if (!next.characters.length && prev.length) return prev;
      return next.characters.map(character => {
        const local = prev.find(item => item.id === character.id);
        return {
          ...character,
          avatar: storedAvatars.characters[character.id] || local?.avatar || null,
          isPinned: local?.isPinned,
          pinnedAt: local?.pinnedAt,
          isHidden: local?.isHidden,
        };
      });
    });
    setRules(prev => {
      // 校规完全以 MVU 为准；任意一次变量刷新都清除前端「待更新」标记，不保留本地文案覆盖
      if (!next.rules.length && prev.length) return prev;
      return next.rules;
    });
    setGroups(next.groups);
    if (!buildingsWritePending.current) {
      setBuildings(prev => (!next.buildings.length && prev.length ? prev : next.buildings));
    }
    setStatusTime(formatStatusTime(next.time));
    setSelectedChar(prev => {
      if (!prev) return prev;
      const latest = next.characters.find(item => item.id === prev.id);
      return latest ? { ...latest, avatar: prev.avatar } : prev;
    });
  }, [mvuData]);

  const handlePlayerChange: Dispatch<SetStateAction<Player>> = updater => {
    setPlayer(prev => {
      const next = typeof updater === 'function' ? updater(prev) : updater;
      if (next.avatar !== prev.avatar) {
        void persistPlayerAvatar(next.avatar).then(saved => {
          if (saved && saved !== next.avatar) {
            setPlayer(current => (current.avatar === next.avatar ? { ...current, avatar: saved } : current));
          }
        }).catch(() => {
          showToast('头像保存失败，刷新后可能会丢失', 'error');
        });
      }
      return next;
    });
  };

  const handleCharacterUpload = (id: string, dataUrl: string) => {
    setCharacters(prev => prev.map(c => (c.id === id ? { ...c, avatar: dataUrl } : c)));
    if (selectedChar?.id === id) {
      setSelectedChar(prev => (prev ? { ...prev, avatar: dataUrl } : null));
    }
    void persistCharacterAvatar(id, dataUrl).then(saved => {
      if (!saved || saved === dataUrl) return;
      setCharacters(prev => prev.map(c => (c.id === id ? { ...c, avatar: saved } : c)));
      if (selectedChar?.id === id) {
        setSelectedChar(prev => (prev ? { ...prev, avatar: saved } : null));
      }
    }).catch(() => {
      showToast('头像保存失败，刷新后可能会丢失', 'error');
    });
  };

  const switchTab = (tab: Tab) => {
    setSelectedChar(null);
    setActiveTab(tab);
  };

  const handleBuildingsChange = async (nextBuildings: CampusBuilding[]) => {
    buildingsWritePending.current = true;
    setBuildings(nextBuildings);
    await setMvuBuildings(nextBuildings);
    window.setTimeout(() => {
      buildingsWritePending.current = false;
    }, 700);
  };

  const renderOverlay = () => {
    if (!activeTab) return null;

    switch (activeTab) {
      case 'profile':
        return (
          <ProfileScreen
            player={player}
            setPlayer={handlePlayerChange}
            characters={characters}
            onCharacterClick={setSelectedChar}
            onClose={() => switchTab(null)}
          />
        );
      case 'contacts':
        return (
          <ContactsScreen
            key="contacts"
            characters={characters}
            setCharacters={setCharacters}
            groups={groups}
            player={player}
            onCharacterClick={setSelectedChar}
            onClose={() => switchTab(null)}
          />
        );
      case 'rules':
        return (
          <RulesScreen
            key="rules"
            rules={rules}
            buildings={buildings}
            onApplyPending={rule => {
              setRules(prev => {
                if (rule.pendingAction === 'add') {
                  return [...prev, { ...rule, pendingUpdate: true, pendingAction: 'add' }];
                }
                const index = prev.findIndex(item => item.id === rule.id);
                if (index < 0) return prev;
                const next = [...prev];
                next[index] = {
                  ...prev[index],
                  pendingUpdate: true,
                  pendingAction: rule.pendingAction,
                };
                return next;
              });
            }}
            onClose={() => switchTab(null)}
          />
        );
      case 'map':
        return (
          <MapScreen
            key="map"
            buildings={buildings}
            onBuildingsChange={handleBuildingsChange}
            characters={characters}
            rules={rules}
            nowTs={mvuTimeToTimestamp(mvuData.时间)}
            onClose={() => switchTab(null)}
            onCharacterClick={setSelectedChar}
          />
        );
      case 'forum':
        return <ForumScreen key="forum" onClose={() => switchTab(null)} />;
      case 'appSettings':
        return <AppSettingsScreen key="appSettings" onClose={() => switchTab(null)} />;
      case 'settings':
        return (
          <SettingsScreen
            key="settings"
            rules={rules}
            buildings={buildings}
            buildingTypes={Object.fromEntries(buildings.map(item => [item.name, item.facilityType || '学习设施']))}
            initialWorkshopModule={initialWorkshopModule}
            onRulesImported={imported => {
              setRules(prev => {
                const next = [...prev, ...imported];
                void setMvuRules(next);
                return next;
              });
            }}
            onBuildingsImported={imported => {
              const next = [...buildings];
              for (const item of imported) {
                const index = next.findIndex(existing => existing.name === item.name || existing.id === item.id);
                if (index >= 0) next[index] = { ...next[index], ...item };
                else next.push(item);
              }
              void handleBuildingsChange(next);
            }}
            onRulesDeleted={ids => {
              setRules(prev => {
                const next = prev.filter(rule => !ids.includes(rule.id));
                void setMvuRules(next);
                return next;
              });
            }}
            onBuildingsDeleted={ids => {
              void handleBuildingsChange(buildings.filter(item => !ids.includes(item.id) && !ids.includes(item.name)));
            }}
            onClose={() => (onCloseToMenu ? onCloseToMenu() : switchTab(null))}
          />
        );
    }
  };

  const navItems: { id: Tab; icon: any; label: string }[] = [
    { id: 'profile', icon: User, label: '个人信息' },
    { id: 'contacts', icon: BookUser, label: '同学录' },
    { id: 'rules', icon: BookOpen, label: '校规手册' },
    { id: 'map', icon: Map, label: '校园地图' },
    { id: 'forum', icon: MessageSquare, label: '论坛' },
    { id: 'settings', icon: Hammer, label: '工坊' },
  ];

  return (
    <div className={`relative phone-frame font-sans w-full h-full transition-transform duration-300 ${isDark ? 'theme-dark' : ''}`}>
      <div
        className={`phone-screen flex flex-col ${isDark ? 'theme-dark' : ''}`}
        style={{ '--phone-nav-height': hideHomeNav ? '0px' : '5rem' } as CSSProperties}
      >
        <div className="absolute top-0 left-1/2 -translate-x-1/2 w-32 h-7 bg-black rounded-b-3xl z-[80]" />

        <div className="absolute top-0 w-full h-12 flex items-center justify-between px-6 z-[80] pointer-events-none">
          <span className="text-xs font-medium text-text-primary mix-blend-difference">{statusTime}</span>
          <div className="flex gap-1.5 items-center mix-blend-difference">
            <div className="w-3.5 h-3.5 border-2 border-gray-800 rounded-sm relative">
              <div className="absolute inset-[1px] bg-gray-800 rounded-sm" />
            </div>
            <div className="w-4 h-3.5 flex items-end gap-[1px]">
              <div className="w-1 h-1.5 bg-gray-800 rounded-sm" />
              <div className="w-1 h-2 bg-gray-800 rounded-sm" />
              <div className="w-1 h-2.5 bg-gray-800 rounded-sm" />
              <div className="w-1 h-3.5 bg-gray-800 rounded-sm" />
            </div>
          </div>
        </div>

        <div className="relative flex-1 pt-12 overflow-hidden">
          <HomeScreen
            player={player}
            characters={characters}
            rules={rules}
            buildings={buildings}
            hasUpdate={hasUpdate}
            onOpenApp={tab => switchTab(tab)}
          />
        </div>

        <AnimatePresence>{renderOverlay()}</AnimatePresence>

        <ToastContainer />

        {!hideHomeNav && (
        <div className="absolute bottom-0 w-full h-20 glass flex items-center justify-around px-2 pb-4 pt-2 z-[80]">
          {navItems.map(item => {
            const isActive = activeTab === item.id;
            return (
              <button
                key={item.id}
                onClick={() => switchTab(isActive ? null : item.id)}
                className={`flex flex-col items-center gap-1 transition-all ${isActive ? 'text-text-primary' : 'text-text-secondary'}`}
              >
                <div className="flex items-center justify-center transition-all duration-300">
                  <item.icon className="w-6 h-6" strokeWidth={isActive ? 2.5 : 2} />
                </div>
                <span className="text-[10px]">{item.label}</span>
              </button>
            );
          })}
        </div>
        )}

        <CharacterModal
          character={selectedChar}
          onClose={() => setSelectedChar(null)}
          onAvatarUpload={handleCharacterUpload}
        />
      </div>
    </div>
  );
}
