function yamlQuote(value: string): string {
  if (/[:#{}[\],&*?|<>=!%@`']/.test(value) || value.includes('\n')) {
    return JSON.stringify(value);
  }
  return value;
}

function renameBuilding(type: string, originalName: string, building: CampusBuildingDef): { name: string; building: CampusBuildingDef } {
  const table = type === '玄幻修仙' ? XIANXIA_RENAMES : type === '魔法学院' ? MAGIC_RENAMES : null;
  const mapped = table?.[originalName];
  if (!mapped) {
    return { name: originalName, building: { ...building, 建筑活动: [] } };
  }
  return {
    name: mapped.name,
    building: {
      ...building,
      建筑描述: mapped.description,
      建筑活动: [],
    },
  };
}

