const BUILDING_TYPES: CampusBuildingDef['建筑类型'][] = ['餐饮娱乐', '学习设施', '运动设施', '宿舍生活', '自然环境'];

function cloneBuildingDef(building: CampusBuildingDef): CampusBuildingDef {
  return {
    X坐标: Number(building.X坐标) || 0,
    Y坐标: Number(building.Y坐标) || 0,
    宽度: Math.max(1, Number(building.宽度) || 1),
    高度: Math.max(1, Number(building.高度) || 1),
    建筑类型: BUILDING_TYPES.includes(building.建筑类型) ? building.建筑类型 : '学习设施',
    建筑描述: String(building.建筑描述 || ''),
    建筑活动: [],
  };
}

export function cloneCampusLayout(buildings: Record<string, CampusBuildingDef>): Record<string, CampusBuildingDef> {
  return Object.fromEntries(
    Object.entries(buildings).map(([name, building]) => [name, cloneBuildingDef(building)]),
  );
}

export function getCampusLayoutBuildings(type: string, trait: string): Record<string, CampusBuildingDef> {
  const layoutType = CAMPUS_TYPES.includes(type as (typeof CAMPUS_TYPES)[number]) ? type : '青春校园';
  const girlsDorm = FALLBACK_CAMPUS_BUILDINGS['女生宿舍'];
  const result: Record<string, CampusBuildingDef> = {};
  for (const [originalName, building] of Object.entries(FALLBACK_CAMPUS_BUILDINGS)) {
    if (trait === '全女' && originalName === '男生宿舍') continue;
    if (trait === '全男' && originalName === '女生宿舍') continue;
    const mapped = renameBuilding(layoutType, originalName, building);
    if (trait === '全男' && originalName === '男生宿舍' && girlsDorm) {
      mapped.building = {
        ...mapped.building,
        X坐标: girlsDorm.X坐标,
        Y坐标: girlsDorm.Y坐标,
        宽度: girlsDorm.宽度,
        高度: girlsDorm.高度,
      };
    }
    result[mapped.name] = mapped.building;
  }
  return result;
}

export function cloneNormalYouthCampusLayout(): Record<string, CampusBuildingDef> {
  return cloneCampusLayout(getCampusLayoutBuildings('青春校园', '正常'));
}

export function sanitizeCampusBuildingMap(raw: unknown): Record<string, CampusBuildingDef> | null {
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return null;
  const result: Record<string, CampusBuildingDef> = {};
  for (const [name, value] of Object.entries(raw as Record<string, any>)) {
    const buildingName = String(name || '').trim();
    if (!buildingName || !value || typeof value !== 'object') continue;
    const x = Number(value.X坐标 ?? value.x);
    const y = Number(value.Y坐标 ?? value.y);
    const width = Number(value.宽度 ?? value.width);
    const height = Number(value.高度 ?? value.height);
    if (![x, y, width, height].every(Number.isFinite)) continue;
    const facilityType = String(value.建筑类型 ?? value.facilityType ?? '');
    result[buildingName] = cloneBuildingDef({
      X坐标: x,
      Y坐标: y,
      宽度: width,
      高度: height,
      建筑类型: (BUILDING_TYPES.includes(facilityType as CampusBuildingDef['建筑类型'])
        ? facilityType
        : '学习设施') as CampusBuildingDef['建筑类型'],
      建筑描述: String(value.建筑描述 ?? value.description ?? ''),
      建筑活动: [],
    });
  }
  return Object.keys(result).length ? result : null;
}

export function buildInitVarFromLayout(buildings: Record<string, CampusBuildingDef>, existing = ''): string {
  const next = replaceCampusBuildingsYaml(existing, buildings);
  const location = pickFallbackLocation(buildings);
  if (!location) return next;
  return next.replace(/当前所在地:\s*.*/, `当前所在地: ${location}`);
}

export function previewBuildingsToLayout(buildings: CampusBuilding[]): Record<string, CampusBuildingDef> {
  const result: Record<string, CampusBuildingDef> = {};
  for (const building of buildings) {
    const name = String(building.name || '').trim();
    if (!name) continue;
    const palette = BUILDING_COLOR_PALETTES.find(item => item.colorClass === building.color);
    result[name] = cloneBuildingDef({
      X坐标: building.x,
      Y坐标: building.y,
      宽度: building.width,
      高度: building.height,
      建筑类型: (building.facilityType && BUILDING_TYPES.includes(building.facilityType as CampusBuildingDef['建筑类型'])
        ? building.facilityType
        : palette?.category || '学习设施') as CampusBuildingDef['建筑类型'],
      建筑描述: String(building.description || ''),
      建筑活动: [],
    });
  }
  return result;
}

export function dumpCampusBuildingsYaml(buildings: Record<string, CampusBuildingDef>): string {
  const lines = ['校园建筑:', '  $meta:', '    extensible: true'];
  for (const [name, building] of Object.entries(buildings)) {
    lines.push(`  ${yamlQuote(name)}:`);
    lines.push(`    X坐标: ${building.X坐标}`);
    lines.push(`    Y坐标: ${building.Y坐标}`);
    lines.push(`    宽度: ${building.宽度}`);
    lines.push(`    高度: ${building.高度}`);
    lines.push(`    建筑类型: ${building.建筑类型}`);
    lines.push(`    建筑描述: ${yamlQuote(building.建筑描述 || '')}`);
    lines.push('    建筑活动: []');
    lines.push('');
  }
  return `${lines.join('\n').trimEnd()}\n`;
}

export function replaceCampusBuildingsYaml(source: string, buildings: Record<string, CampusBuildingDef>): string {
  const block = dumpCampusBuildingsYaml(buildings).trimEnd();
  const base = source.trim() ? source : INITVAR_PREFIX;
  if (/^校园建筑:/m.test(base)) {
    return `${base.replace(/\n?校园建筑:[\s\S]*$/, '')}\n\n${block}\n`;
  }
  return `${base.replace(/\s*$/, '')}\n\n${block}\n`;
}

export function getBuildingColorClass(type: string): string {
  return BUILDING_COLOR_PALETTES.find(item => item.category === type)?.colorClass || BUILDING_COLOR_PALETTES[1].colorClass;
}

export function campusLayoutToPreviewBuildings(buildings: Record<string, CampusBuildingDef>): CampusBuilding[] {
  return Object.entries(buildings).map(([name, building]) => ({
    id: /大门|山门/.test(name) ? 'gate' : name,
    name,
    x: building.X坐标,
    y: building.Y坐标,
    width: building.宽度,
    height: building.高度,
    color: getBuildingColorClass(building.建筑类型),
    description: building.建筑描述,
    facilityType: building.建筑类型,
  }));
}

export function pickFallbackLocation(buildings: Record<string, CampusBuildingDef>, current?: string): string {
  const names = Object.keys(buildings);
  if (current && names.includes(current)) return current;
  const preferred = names.find(name => /大门|山门/.test(name));
  return preferred || names[0] || '';
}
