export function resolveWorldRuleContent(ruleEffectId: RuleEffectId | string | undefined): string {
  return ruleEffectId === 'forced' ? FORCED_WORLD_RULE_CONTENT : ACCEPTED_WORLD_RULE_CONTENT;
}

export function getWorldRuleModeLabel(ruleEffectId: RuleEffectId | string | undefined): string {
  return ruleEffectId === 'forced' ? '强制校规模式' : '平然校规模式';
}
